 "steps": [
  {
   "id": "projects",
   "title": "Projects",
   "subtitle": "Pick the .NET version and the projects to create. The sites only talk to the API, so the API is created whenever a site is selected.",
   "fields": [
    "Framework",
    "IncludeInternal",
    "IncludeExternal",
    "IncludeApi",
    "IncludeServices",
    "IncludeSqlRepository",
    "IncludeTests"
   ]
  },
  {
   "id": "database",
   "title": "Database",
   "subtitle": "Choose the database the API uses and test the connection before you create the solution.",
   "when": [
    {
     "IncludeSqlRepository": [
      "true"
     ]
    },
    {
     "IncludeServices": [
      "true"
     ]
    },
    {
     "IncludeInternal": [
      "true"
     ],
     "InternalAuthentication": [
      "Identity"
     ]
    },
    {
     "IncludeExternal": [
      "true"
     ],
     "ExternalAuthentication": [
      "Identity"
     ]
    }
   ],
   "fields": [
    "DatabaseProvider",
    "SqlServerVersion",
    "PostgresVersion",
    "DbAuthentication",
    "DbServer",
    "DbName",
    "DbUser",
    "DbPassword",
    "ConnectionString",
    "SeedSampleData"
   ],
   "testConnection": true
  },
  {
   "id": "api",
   "title": "API, security & sign-in",
   "subtitle": "Options for ProjectName.API, error monitoring, and how staff and customers sign in to the sites.",
   "fields": [
    "ApiDocumentation",
    "IncludeApiKey",
    "IncludeHealthChecks",
    "IncludeSerilog",
    "ErrorMonitoring",
    "ErrorMonitoringKey",
    "InternalAuthentication",
    "EntraTenantId",
    "EntraClientId",
    "ExternalAuthentication",
    "IdentitySignIn",
    "IdentityTwoFactor",
    "IdentityPasskeys",
    "IdentityAdminUi",
    "IncludeResilience"
   ]
  },
  {
   "id": "frontend",
   "title": "Front end",
   "subtitle": "Client-side libraries for the Internal and External sites. LibMan restores them into wwwroot/lib on build.",
   "when": [
    {
     "IncludeInternal": [
      "true"
     ]
    },
    {
     "IncludeExternal": [
      "true"
     ]
    }
   ],
   "fields": [
    "JQueryVersion",
    "JQueryUIVersion",
    "JQueryUITheme",
    "BootstrapVersion",
    "BootstrapTheme",
    "FontAwesomeVersion",
    "IncludeJQueryValidation",
    "IncludeDataTables",
    "IncludeSelect2",
    "IncludeToastr",
    "IncludeSweetAlert",
    "IncludeChartJs"
   ]
  },
  {
   "id": "summary",
   "title": "Summary",
   "subtitle": "Check your choices. Create runs the dotnet new command below and opens the solution.",
   "fields": []
  }
 ],
